{
  "name": "opencode-slim-output",
  "version": "0.1.2",
  "description": "OpenCode plugin: fail-closed post-processor that collapses external stack frames, relativizes paths and dedups repetitive output.",
  "type": "module",
  "main": "plugin.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mateocerri/opencode-slim-output.git"
  },
  "homepage": "https://www.npmjs.com/package/opencode-slim-output",
  "author": "Mateo Cerri",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "output",
    "stack-trace",
    "wsl"
  ],
  "files": [
    "plugin.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test \"tests/*.test.ts\"",
    "typecheck": "npx tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.26"
  },
  "devDependencies": {
    "@types/node": "^24.19.2",
    "typescript": "^5.6.0"
  },
  "license": "MIT"
}
